import{z as p,x as c,o as s,c as E,q as t,j as r,D as n,d as i,s as l,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"Windows NT 对照","description":"","frontmatter":{"title":"Windows NT 对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/windows-nt-contrast.md","filePath":"cs/windows-nt-contrast.md","lastUpdated":1791413859000}'),u={name:"cs/windows-nt-contrast.md"};function A(T,a,m,B,I,N){const o=c("Mermaid");return s(),E("div",null,[a[2]||(a[2]=t('<h1 id="windows-nt-对照" tabindex="-1">Windows NT 对照 <a class="header-anchor" href="#windows-nt-对照" aria-label="Permalink to &quot;Windows NT 对照&quot;">​</a></h1><div class="epigraph"><p>NT 用对象管理器统一进程、文件、设备：句柄表、I/O 请求包 IRP、注册表，而不是「一切皆 Unix 文件描述符」的同一套。</p><footer>—— 据 Russinovich, Solomon, Ionescu, <em>Windows Internals</em>；[VFS](/cs/vfs) 与 [设备模型](/cs/device-model-binding) 为 Linux 侧先修</footer></div><p><a href="/cs/rust-in-kernel">Rust in kernel</a> 仍在 Linux。课程序列需要 <strong>对照</strong>：同一问题 NT 如何切对象。不是教你写 NT 驱动教程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>句柄：带访问权的对象指针。IRP：异步 I/O 的统一包，类似 bio+skb 的职务在 I/O 管理器。缺口：NT 命名空间 <code>\\Device\\...</code> vs Unix <code>/dev</code>；作业对象约等于 job≈cgroup 亲戚。本课不把 Win32 与 NT 原生 API 的每一层写完。</p><p><span class="marginnote">术语翻译：句柄就是「带权限标记的取货单」——对象本体在内核里，进程手里只拿一张记着访问权的票据；Unix 的 fd 是它的近亲，但 NT 的票在创建时就写死了允许哪些操作。</span></p><p><span class="marginnote">Hyper-V 类型 1 与 NT 的关系：NT 可当根分区。对象是内核架构对照。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照表只点：调度（优先级+量子 vs CFS/EEVDF）、内存（工作集 vs RSS/memcg）、文件（NTFS vs ext4 已在 FS 课）、网络（NDIS vs sk_buff）。对照 <a href="/cs/linux-capabilities">capabilities</a>：NT 是 ACL+特权。对照 <a href="/cs/chardev-ioctl">ioctl</a>：DeviceIoControl/IRP_MJ_DEVICE_CONTROL。</p>',9)),(s(),r(d,null,{default:n(()=>[l(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22NT%20%E5%AF%B9%E8%B1%A1%E7%AE%A1%E7%90%86%E5%99%A8%22%5D%20--%3E%20H%5B%22%E5%8F%A5%E6%9F%84%22%5D%0A%20%20IO%5B%22I%2FO%20%E7%AE%A1%E7%90%86%E5%99%A8%22%5D%20--%3E%20IRP%5B%22IRP%22%5D%0A%20%20IRP%20--%3E%20DRV%5B%22%E9%A9%B1%E5%8A%A8%E6%A0%88%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[i("NT 证明宏内核不必 Unix 形状：对象+IRP 同样能覆盖进程与设备。可移植课序要求会翻译，而不是背命令。不要写成哪边更好。与 "),e("a",{href:"/cs/lsm-selinux"},"SELinux"),i("：MIC/完整性级别是另一套 MAC。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：IRP 像医院的检查申请单——I/O 管理器开单，逐层往各科室（驱动栈）传递盖章，任何一环都可以说「我稍后回复」（异步完成）；Unix 的 bio 只管块存储这一类，IRP 是全类型 I/O 的统一单据。")],-1)),(s(),r(d,null,{default:n(()=>[l(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20FD%5B%22Unix%20%E6%96%87%E4%BB%B6%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%20--%3E%20H2%5B%22NT%20%E5%8F%A5%E6%9F%84%22%5D%0A%20%20VFS2%5B%22Unix%20VFS%22%5D%20--%3E%20OM%5B%22NT%20%E5%AF%B9%E8%B1%A1%E7%AE%A1%E7%90%86%E5%99%A8%22%5D%0A%20%20BIO%5B%22bio%20%2F%20sk_buff%22%5D%20--%3E%20IRP2%5B%22IRP%22%5D%0A%20%20CG%5B%22cgroup%22%5D%20--%3E%20JOB%5B%22%E4%BD%9C%E4%B8%9A%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20IOC%5B%22ioctl%22%5D%20--%3E%20DIC%5B%22DeviceIoControl%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>用户态子系统（Win32、WSL）说明 ABI 可叠在 NT 上——WSL2 实际是轻量 VM，接回 <a href="/cs/hypervisor-types">Hypervisor</a> 课。</p><p>实现上：IRP 可在驱动栈里同步或异步完成，取消路径复杂。作业对象限 CPU/内存，像 cgroup 的远亲。WSL2 用轻量 VM，对照的是 Hyper-V，不是 NT 原生 Unix。 读法上只引用<a href="/cs/rust-in-kernel">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / 容器与内核形态」课序里，对象是 <strong>Windows NT 对照</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有执行体组件。不保证 ReactOS。下一课课序封口：分布式 OS 直觉。</p><p>版本字段会变，课序钉的是机制对象「Windows NT 对照」，不是某一主线内核的结构体名。 后课默认：宏内核可以是 NT 对象模型。多机看起来像一台 OS 的限度，下一课。</p><p><span class="marginnote">常见误区：以为 WSL2 是「Windows 里做 Linux 系统调用翻译」——那是 WSL1；WSL2 跑的是轻量虚拟机里的真 Linux 内核，走 Hyper-V 虚拟化，与 NT 原生 ABI 无关。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NT：对象管理器、句柄、IRP。</li><li>与 Linux 的 VFS/cgroup/skb 是同问题不同切法。</li><li>分布式 OS 直觉是下一课。</li><li>出处：<em>Windows Internals</em>；Tanenbaum 对照。</li></ul>',10))])}const S=p(u,[["render",A]]);export{h as __pageData,S as default};
